/**
 * Viewport state and coordinate transformations
 * Converts between world coordinates (nanometers, Y-up) and screen coordinates (pixels, Y-down)
 */

export interface Viewport {
  // View center in world coordinates (nanometers)
  centerX: number;
  centerY: number;
  // Pixels per nanometer
  scale: number;
  // Canvas dimensions
  width: number;
  height: number;
}

/**
 * Create a new viewport with default zoom
 * Default scale: 1mm = 100px (reasonable starting zoom)
 * 1mm = 1,000,000 nm, so scale = 100 / 1,000,000 = 0.0001
 */
export function createViewport(width: number, height: number): Viewport {
  return {
    centerX: 0,
    centerY: 0,
    scale: 0.0001,
    width,
    height,
  };
}

/**
 * Convert world coordinates (nm, Y-up) to screen coordinates (px, Y-down)
 */
export function worldToScreen(vp: Viewport, worldX: number, worldY: number): [number, number] {
  const screenX = (worldX - vp.centerX) * vp.scale + vp.width / 2;
  // Y is flipped: world Y-up to screen Y-down
  const screenY = vp.height / 2 - (worldY - vp.centerY) * vp.scale;
  return [screenX, screenY];
}

/**
 * Convert screen coordinates (px, Y-down) to world coordinates (nm, Y-up)
 */
export function screenToWorld(vp: Viewport, screenX: number, screenY: number): [number, number] {
  const worldX = (screenX - vp.width / 2) / vp.scale + vp.centerX;
  // Y is flipped
  const worldY = vp.centerY - (screenY - vp.height / 2) / vp.scale;
  return [worldX, worldY];
}

/**
 * Zoom at a specific screen point (cursor position)
 * The world point under the cursor stays at the same screen position after zoom
 */
export function zoomAtPoint(vp: Viewport, screenX: number, screenY: number, factor: number): Viewport {
  // Get world point before zoom
  const [worldX, worldY] = screenToWorld(vp, screenX, screenY);

  // Apply zoom with clamping
  // Min: 0.000001 px/nm = 1mm takes 1px (very zoomed out)
  // Max: 0.01 px/nm = 1mm takes 10,000px (very zoomed in)
  const newScale = Math.max(0.000001, Math.min(0.01, vp.scale * factor));

  // Adjust center so world point stays at same screen position
  const newCenterX = worldX - (screenX - vp.width / 2) / newScale;
  const newCenterY = worldY + (screenY - vp.height / 2) / newScale;

  return {
    ...vp,
    scale: newScale,
    centerX: newCenterX,
    centerY: newCenterY,
  };
}

/**
 * Pan by screen delta (pixels)
 */
export function pan(vp: Viewport, dx: number, dy: number): Viewport {
  return {
    ...vp,
    centerX: vp.centerX - dx / vp.scale,
    centerY: vp.centerY + dy / vp.scale, // Invert Y for world coords
  };
}

/**
 * Fit board in viewport with padding
 */
export function fitBoard(vp: Viewport, boardWidth: number, boardHeight: number, padding: number = 50): Viewport {
  // Guard against zero dimensions
  if (boardWidth <= 0 || boardHeight <= 0) {
    return vp;
  }

  const scaleX = (vp.width - padding * 2) / boardWidth;
  const scaleY = (vp.height - padding * 2) / boardHeight;
  const scale = Math.min(scaleX, scaleY);

  return {
    ...vp,
    centerX: boardWidth / 2,
    centerY: boardHeight / 2,
    scale,
  };
}

/**
 * Update viewport dimensions (on canvas resize)
 */
export function resizeViewport(vp: Viewport, width: number, height: number): Viewport {
  return {
    ...vp,
    width,
    height,
  };
}

/**
 * Hit-testing for traces — converts a screen click to the nearest trace.
 * Uses perpendicular distance from point to each segment, accounting for trace copper width.
 */

import type { BoardSnapshot, TraceInfo } from './types';
import type { Viewport } from './viewport';
import { screenToWorld } from './viewport';

export interface HitTestResult {
  trace: TraceInfo;
  segmentIndex: number;
}

/**
 * Compute the minimum distance from a point to a line segment.
 * All coordinates in the same unit (nanometers).
 */
function pointToSegmentDistance(
  px: number, py: number,
  ax: number, ay: number,
  bx: number, by: number,
): number {
  const dx = bx - ax;
  const dy = by - ay;
  const lenSq = dx * dx + dy * dy;

  if (lenSq === 0) {
    // Degenerate segment (zero length)
    const ex = px - ax;
    const ey = py - ay;
    return Math.sqrt(ex * ex + ey * ey);
  }

  // Parameter t for projection of P onto line AB, clamped to [0,1]
  let t = ((px - ax) * dx + (py - ay) * dy) / lenSq;
  t = Math.max(0, Math.min(1, t));

  // Closest point on segment
  const cx = ax + t * dx;
  const cy = ay + t * dy;

  const ex = px - cx;
  const ey = py - cy;
  return Math.sqrt(ex * ex + ey * ey);
}

/**
 * Find the trace closest to the given screen coordinates.
 *
 * @param snapshot   Current board snapshot
 * @param viewport   Current viewport state
 * @param screenX    Click X in screen pixels
 * @param screenY    Click Y in screen pixels
 * @param tolerancePx  Extra tolerance in screen pixels (beyond trace copper width)
 * @returns The closest trace and segment index, or null if nothing is within tolerance.
 */
export function hitTestTrace(
  snapshot: BoardSnapshot | null,
  viewport: Viewport,
  screenX: number,
  screenY: number,
  tolerancePx: number = 5,
): HitTestResult | null {
  if (!snapshot?.traces || snapshot.traces.length === 0) return null;

  const [worldX, worldY] = screenToWorld(viewport, screenX, screenY);
  // Convert pixel tolerance to world units (nanometers)
  const toleranceNm = tolerancePx / viewport.scale;

  let bestDist = Infinity;
  let bestTrace: TraceInfo | null = null;
  let bestSegIdx = 0;

  for (const trace of snapshot.traces) {
    // Total tolerance = pixel tolerance in nm + half the trace copper width
    const hitRadius = toleranceNm + trace.width / 2;

    for (let i = 0; i < trace.segments.length; i++) {
      const seg = trace.segments[i];
      const dist = pointToSegmentDistance(
        worldX, worldY,
        seg.start_x, seg.start_y,
        seg.end_x, seg.end_y,
      );
      if (dist <= hitRadius && dist < bestDist) {
        bestDist = dist;
        bestTrace = trace;
        bestSegIdx = i;
      }
    }
  }

  if (bestTrace) {
    return { trace: bestTrace, segmentIndex: bestSegIdx };
  }
  return null;
}

/**
 * Undo/Redo system using the command pattern.
 *
 * Each board mutation is wrapped in a BoardCommand that knows how to
 * execute and reverse itself. The UndoStack manages a linear history
 * with a maximum depth of 100.
 *
 * Debug surface: window.__undoStack exposes { canUndo, canRedo, depth, lastCommand }
 */

import type { PcbEngine } from './wasm';

// ---------------------------------------------------------------------------
// Command interface
// ---------------------------------------------------------------------------

export interface BoardCommand {
  /** Human-readable description for logs and debug */
  description: string;
  /** Perform the mutation */
  execute(): void;
  /** Reverse the mutation */
  undo(): void;
}

// ---------------------------------------------------------------------------
// UndoStack
// ---------------------------------------------------------------------------

const MAX_DEPTH = 100;

export class UndoStack {
  private history: BoardCommand[] = [];
  /** Points to the next slot to write into — commands before this index are undoable */
  private cursor = 0;

  get canUndo(): boolean {
    return this.cursor > 0;
  }

  get canRedo(): boolean {
    return this.cursor < this.history.length;
  }

  get depth(): number {
    return this.history.length;
  }

  get lastCommand(): string | null {
    if (this.cursor === 0) return null;
    return this.history[this.cursor - 1].description;
  }

  /**
   * Execute a command and push it onto the stack.
   * Clears any redo history beyond the current cursor.
   */
  push(cmd: BoardCommand): void {
    cmd.execute();
    console.log(`[Undo] Execute: ${cmd.description}`);

    // Truncate redo tail
    this.history.length = this.cursor;

    this.history.push(cmd);
    this.cursor++;

    // Enforce max depth — drop oldest
    if (this.history.length > MAX_DEPTH) {
      this.history.shift();
      this.cursor--;
    }
  }

  /**
   * Undo the last executed command. No-op if nothing to undo.
   */
  undo(): void {
    if (!this.canUndo) {
      console.warn('[Undo] Nothing to undo');
      return;
    }
    this.cursor--;
    const cmd = this.history[this.cursor];
    cmd.undo();
    console.log(`[Undo] Undo: ${cmd.description}`);
  }

  /**
   * Redo the last undone command. No-op if nothing to redo.
   */
  redo(): void {
    if (!this.canRedo) {
      console.warn('[Undo] Nothing to redo');
      return;
    }
    const cmd = this.history[this.cursor];
    cmd.execute();
    console.log(`[Undo] Redo: ${cmd.description}`);
    this.cursor++;
  }

  /**
   * Clear all history (e.g. on file load).
   */
  clear(): void {
    this.history.length = 0;
    this.cursor = 0;
    console.log('[Undo] Stack cleared');
  }
}

// ---------------------------------------------------------------------------
// Trace commands
// ---------------------------------------------------------------------------

export interface AddTraceArgs {
  netName: string;
  layer: string;
  width: number;
  /** Flat segment array [x1,y1,x2,y2, ...] */
  segments: number[];
}

/**
 * Command: add a trace to the board.
 *
 * On execute, calls engine.add_trace and stores the returned ID.
 * On undo, calls engine.remove_trace with that ID.
 */
export class AddTraceCommand implements BoardCommand {
  description: string;
  private traceId: number = 0xFFFFFFFF;

  constructor(
    private engine: PcbEngine,
    private args: AddTraceArgs,
    private refreshSnapshot: () => void,
  ) {
    this.description = `Add trace: ${args.netName} on ${args.layer}`;
  }

  execute(): void {
    this.traceId = this.engine.add_trace(
      this.args.netName,
      this.args.layer,
      this.args.width,
      this.args.segments,
    );
    if (this.traceId === 0xFFFFFFFF) {
      console.warn(`[Undo] AddTraceCommand: engine.add_trace failed for net=${this.args.netName}`);
    }
    this.engine.run_drc_incremental();
    this.refreshSnapshot();
  }

  undo(): void {
    if (this.traceId !== 0xFFFFFFFF) {
      this.engine.remove_trace(this.traceId);
      this.engine.run_drc_incremental();
    }
    this.refreshSnapshot();
  }
}

/**
 * Command: remove a trace from the board.
 *
 * On execute, removes the trace.
 * On undo, re-adds it with the original parameters.
 */
export class RemoveTraceCommand implements BoardCommand {
  description: string;
  /** Re-created trace ID after undo (may differ from original) */
  private restoredId: number = 0xFFFFFFFF;

  constructor(
    private engine: PcbEngine,
    private traceId: number,
    private args: AddTraceArgs,
    private refreshSnapshot: () => void,
  ) {
    this.description = `Remove trace: ${args.netName} (id=${traceId})`;
  }

  execute(): void {
    this.engine.remove_trace(this.traceId);
    this.engine.run_drc_incremental();
    this.refreshSnapshot();
  }

  undo(): void {
    this.restoredId = this.engine.add_trace(
      this.args.netName,
      this.args.layer,
      this.args.width,
      this.args.segments,
    );
    if (this.restoredId === 0xFFFFFFFF) {
      console.warn(`[Undo] RemoveTraceCommand.undo: re-add failed for net=${this.args.netName}`);
    } else {
      // Update trace ID so future execute() uses the new ID
      this.traceId = this.restoredId;
    }
    this.engine.run_drc_incremental();
    this.refreshSnapshot();
  }
}

// ---------------------------------------------------------------------------
// Rotation command
// ---------------------------------------------------------------------------

/**
 * Command: rotate a component by delta millidegrees.
 *
 * On execute, rotates by +delta. On undo, rotates by -delta.
 */
export class RotateComponentCommand implements BoardCommand {
  description: string;

  constructor(
    private engine: PcbEngine,
    private refdes: string,
    private deltaMdeg: number,
    private refreshSnapshot: () => void,
  ) {
    const degrees = deltaMdeg / 1000;
    const sign = degrees > 0 ? '+' : '';
    this.description = `Rotate ${refdes} ${sign}${degrees}°`;
  }

  execute(): void {
    const ok = this.engine.rotate_component(this.refdes, this.deltaMdeg);
    if (!ok) {
      console.warn(`[Undo] RotateComponentCommand: ${this.refdes} not found`);
    }
    this.refreshSnapshot();
  }

  undo(): void {
    const ok = this.engine.rotate_component(this.refdes, -this.deltaMdeg);
    if (!ok) {
      console.warn(`[Undo] RotateComponentCommand.undo: ${this.refdes} not found`);
    }
    this.refreshSnapshot();
  }
}

// ---------------------------------------------------------------------------
// Board resize command
// ---------------------------------------------------------------------------

/**
 * Command: resize the board outline.
 *
 * Stores old and new dimensions. Execute sets new, undo restores old.
 */
export class ResizeBoardCommand implements BoardCommand {
  description: string;

  constructor(
    private engine: PcbEngine,
    private oldWidth: number,
    private oldHeight: number,
    private newWidth: number,
    private newHeight: number,
    private refreshSnapshot: () => void,
  ) {
    const owMm = (oldWidth / 1e6).toFixed(1);
    const ohMm = (oldHeight / 1e6).toFixed(1);
    const nwMm = (newWidth / 1e6).toFixed(1);
    const nhMm = (newHeight / 1e6).toFixed(1);
    this.description = `Resize board: ${owMm}×${ohMm}mm → ${nwMm}×${nhMm}mm`;
  }

  execute(): void {
    const ok = this.engine.set_board_size(this.newWidth, this.newHeight);
    if (!ok) {
      console.warn('[Undo] ResizeBoardCommand: set_board_size failed');
    }
    this.refreshSnapshot();
  }

  undo(): void {
    const ok = this.engine.set_board_size(this.oldWidth, this.oldHeight);
    if (!ok) {
      console.warn('[Undo] ResizeBoardCommand.undo: set_board_size failed');
    }
    this.refreshSnapshot();
  }
}

// ---------------------------------------------------------------------------
// Debug surface
// ---------------------------------------------------------------------------

/**
 * Install the debug surface on window.__undoStack.
 */
export function installDebugSurface(stack: UndoStack): void {
  (window as any).__undoStack = {
    get canUndo() { return stack.canUndo; },
    get canRedo() { return stack.canRedo; },
    get depth() { return stack.depth; },
    get lastCommand() { return stack.lastCommand; },
  };
}

/**
 * URL state encoding and decoding for sharing design views
 * Enables collaboration by encoding viewport and layer visibility in shareable URLs
 */

export interface ViewState {
  layers: string[];      // e.g. ['top', 'bottom', 'ratsnest']
  zoom: number;
  panX: number;
  panY: number;
}

/**
 * Encode view state to URL query parameters
 * Uses short parameter names to keep URLs compact
 */
export function encodeViewState(state: ViewState): string {
  const params = new URLSearchParams();
  params.set('l', state.layers.join(','));
  params.set('z', state.zoom.toFixed(2));
  params.set('x', Math.round(state.panX).toString());
  params.set('y', Math.round(state.panY).toString());
  return '?' + params.toString();
}

/**
 * Decode view state from URL query parameters
 * Returns null if no view state is present in URL
 */
export function decodeViewState(): ViewState | null {
  const params = new URLSearchParams(window.location.search);
  if (!params.has('l')) return null;
  return {
    layers: (params.get('l') || '').split(',').filter(Boolean),
    zoom: parseFloat(params.get('z') || '1'),
    panX: parseFloat(params.get('x') || '0'),
    panY: parseFloat(params.get('y') || '0'),
  };
}

