import { describe, it, expect } from 'vitest';
import {
  createViewport,
  worldToScreen,
  screenToWorld,
  zoomAtPoint,
  pan,
  fitBoard,
  resizeViewport,
  type Viewport,
} from '../viewport';

const vp800x600 = (): Viewport => createViewport(800, 600);

describe('worldToScreen / screenToWorld roundtrip', () => {
  it('center of viewport maps to center of world', () => {
    const vp = vp800x600();
    const [sx, sy] = worldToScreen(vp, 0, 0);
    expect(sx).toBeCloseTo(400);
    expect(sy).toBeCloseTo(300);
  });

  it('roundtrip preserves coordinates', () => {
    const vp = vp800x600();
    const worldPt: [number, number] = [5_000_000, -3_000_000]; // 5mm, -3mm
    const screen = worldToScreen(vp, worldPt[0], worldPt[1]);
    const back = screenToWorld(vp, screen[0], screen[1]);
    expect(back[0]).toBeCloseTo(worldPt[0], 0);
    expect(back[1]).toBeCloseTo(worldPt[1], 0);
  });

  it('roundtrip works for off-center viewport', () => {
    const vp: Viewport = { centerX: 10_000_000, centerY: 5_000_000, scale: 0.0002, width: 1024, height: 768 };
    const worldPt: [number, number] = [12_000_000, 6_000_000];
    const screen = worldToScreen(vp, worldPt[0], worldPt[1]);
    const back = screenToWorld(vp, screen[0], screen[1]);
    expect(back[0]).toBeCloseTo(worldPt[0], 0);
    expect(back[1]).toBeCloseTo(worldPt[1], 0);
  });

  it('Y-axis is flipped (positive world Y goes up on screen)', () => {
    const vp = vp800x600();
    const [, syPos] = worldToScreen(vp, 0, 1_000_000);  // 1mm up
    const [, syNeg] = worldToScreen(vp, 0, -1_000_000); // 1mm down
    // Positive world Y -> smaller screen Y (higher up)
    expect(syPos).toBeLessThan(syNeg);
  });
});

describe('zoomAtPoint', () => {
  it('preserves world-space point under cursor after zoom', () => {
    const vp = vp800x600();
    const screenPt: [number, number] = [200, 150];
    const worldBefore = screenToWorld(vp, screenPt[0], screenPt[1]);

    const zoomed = zoomAtPoint(vp, screenPt[0], screenPt[1], 2.0);
    const worldAfter = screenToWorld(zoomed, screenPt[0], screenPt[1]);

    expect(worldAfter[0]).toBeCloseTo(worldBefore[0], 0);
    expect(worldAfter[1]).toBeCloseTo(worldBefore[1], 0);
  });

  it('increases scale when factor > 1', () => {
    const vp = vp800x600();
    const zoomed = zoomAtPoint(vp, 400, 300, 2.0);
    expect(zoomed.scale).toBeCloseTo(vp.scale * 2);
  });

  it('clamps scale to min/max bounds', () => {
    const vp = vp800x600();
    const zoomedOut = zoomAtPoint(vp, 400, 300, 0.00001);
    expect(zoomedOut.scale).toBeGreaterThanOrEqual(0.000001);

    const zoomedIn = zoomAtPoint(vp, 400, 300, 1_000_000);
    expect(zoomedIn.scale).toBeLessThanOrEqual(0.01);
  });
});

describe('pan', () => {
  it('offsets center correctly for rightward pan', () => {
    const vp = vp800x600();
    const panned = pan(vp, 100, 0); // drag right 100px
    // Dragging right = moving viewport left in world = centerX decreases
    expect(panned.centerX).toBeLessThan(vp.centerX);
    expect(panned.centerY).toEqual(vp.centerY);
  });

  it('offsets center correctly for downward pan', () => {
    const vp = vp800x600();
    const panned = pan(vp, 0, 100); // drag down 100px
    // Dragging down = moving viewport up in world = centerY increases (Y-up)
    expect(panned.centerY).toBeGreaterThan(vp.centerY);
  });

  it('world displacement matches pixel displacement / scale', () => {
    const vp = vp800x600();
    const panned = pan(vp, 50, -30);
    expect(panned.centerX).toBeCloseTo(vp.centerX - 50 / vp.scale);
    expect(panned.centerY).toBeCloseTo(vp.centerY + (-30) / vp.scale);
  });
});

describe('fitBoard', () => {
  it('centers on the board', () => {
    const vp = vp800x600();
    const boardW = 50_000_000; // 50mm
    const boardH = 30_000_000; // 30mm
    const fitted = fitBoard(vp, boardW, boardH);
    expect(fitted.centerX).toEqual(boardW / 2);
    expect(fitted.centerY).toEqual(boardH / 2);
  });

  it('produces a viewport that contains the entire board with padding', () => {
    const vp = vp800x600();
    const boardW = 50_000_000;
    const boardH = 30_000_000;
    const fitted = fitBoard(vp, boardW, boardH, 50);

    // All four corners should map to within the padded viewport
    const corners: [number, number][] = [
      [0, 0], [boardW, 0], [boardW, boardH], [0, boardH],
    ];
    for (const [wx, wy] of corners) {
      const [sx, sy] = worldToScreen(fitted, wx, wy);
      expect(sx).toBeGreaterThanOrEqual(0);
      expect(sx).toBeLessThanOrEqual(fitted.width);
      expect(sy).toBeGreaterThanOrEqual(0);
      expect(sy).toBeLessThanOrEqual(fitted.height);
    }
  });

  it('returns original viewport for zero dimensions', () => {
    const vp = vp800x600();
    const fitted = fitBoard(vp, 0, 100);
    expect(fitted).toEqual(vp);
  });
});

describe('resizeViewport', () => {
  it('updates dimensions without changing center or scale', () => {
    const vp: Viewport = { centerX: 100, centerY: 200, scale: 0.001, width: 800, height: 600 };
    const resized = resizeViewport(vp, 1920, 1080);
    expect(resized.width).toEqual(1920);
    expect(resized.height).toEqual(1080);
    expect(resized.centerX).toEqual(100);
    expect(resized.centerY).toEqual(200);
    expect(resized.scale).toEqual(0.001);
  });
});

import { describe, it, expect } from 'vitest';
import { hitTestTrace } from '../hit-test';
import type { BoardSnapshot, TraceInfo } from '../types';
import type { Viewport } from '../viewport';

/** Helper: build a minimal viewport centered at origin */
function makeViewport(opts?: Partial<Viewport>): Viewport {
  return {
    centerX: 0,
    centerY: 0,
    scale: 0.0001, // 1mm = 100px
    width: 800,
    height: 600,
    ...opts,
  };
}

/** Helper: build a minimal trace */
function makeTrace(segments: { sx: number; sy: number; ex: number; ey: number }[], width = 200_000, id = 1): TraceInfo {
  return {
    id,
    segments: segments.map(s => ({
      start_x: s.sx,
      start_y: s.sy,
      end_x: s.ex,
      end_y: s.ey,
    })),
    width,
    layer: 'F.Cu',
    net_name: 'GND',
    locked: false,
  };
}

/** Helper: build a snapshot from traces */
function makeSnapshot(traces: TraceInfo[]): BoardSnapshot {
  return {
    board: null,
    components: [],
    nets: [],
    violations: [],
    traces,
    vias: [],
    ratsnest: [],
  };
}

describe('hitTestTrace', () => {
  it('returns correct trace for point near a horizontal segment', () => {
    const vp = makeViewport();
    // Horizontal trace at world Y=0, from x=0 to x=10mm
    const trace = makeTrace([{ sx: 0, sy: 0, ex: 10_000_000, ey: 0 }]);
    const snapshot = makeSnapshot([trace]);

    // Click at screen center (maps to world 0,0 which is on the trace)
    const result = hitTestTrace(snapshot, vp, 400, 300, 5);
    expect(result).not.toBeNull();
    expect(result!.trace.id).toEqual(1);
    expect(result!.segmentIndex).toEqual(0);
  });

  it('returns null for point far from any trace', () => {
    const vp = makeViewport();
    // Trace at world origin, horizontal
    const trace = makeTrace([{ sx: 0, sy: 0, ex: 10_000_000, ey: 0 }]);
    const snapshot = makeSnapshot([trace]);

    // Click far away — top-left corner of screen, maps to world far from trace
    // screen (0,0) -> world: (-4_000_000, 3_000_000) — 3mm away from trace
    const result = hitTestTrace(snapshot, vp, 0, 0, 5);
    expect(result).toBeNull();
  });

  it('handles vertical segments', () => {
    const vp = makeViewport();
    // Vertical trace from (0,0) to (0, 10mm)
    const trace = makeTrace([{ sx: 0, sy: 0, ex: 0, ey: 10_000_000 }]);
    const snapshot = makeSnapshot([trace]);

    // Click at screen center (world 0,0) — on the trace start
    const result = hitTestTrace(snapshot, vp, 400, 300, 5);
    expect(result).not.toBeNull();
    expect(result!.trace.id).toEqual(1);
  });

  it('handles diagonal segments', () => {
    const vp = makeViewport();
    // 45-degree trace from (0,0) to (5mm, 5mm)
    const trace = makeTrace([{ sx: 0, sy: 0, ex: 5_000_000, ey: 5_000_000 }]);
    const snapshot = makeSnapshot([trace]);

    // Click at world origin (on the trace start)
    const result = hitTestTrace(snapshot, vp, 400, 300, 5);
    expect(result).not.toBeNull();
  });

  it('respects trace width — wider traces are easier to hit', () => {
    const vp = makeViewport();
    // Thin trace (0.1mm width) at world y=500_000 (0.5mm above center)
    // Distance from center = 0.5mm = 500_000nm
    // Tolerance in world = 5px / 0.0001 = 50_000nm
    // Hit radius = 50_000 + 50_000 (half of 0.1mm) = 100_000nm — too small for 500_000 distance
    const thinTrace = makeTrace([{ sx: -5_000_000, sy: 500_000, ex: 5_000_000, ey: 500_000 }], 100_000, 1);

    // Wide trace (2mm width) at same position
    // Hit radius = 50_000 + 1_000_000 (half of 2mm) = 1_050_000nm — enough for 500_000 distance
    const wideTrace = makeTrace([{ sx: -5_000_000, sy: 500_000, ex: 5_000_000, ey: 500_000 }], 2_000_000, 2);

    // With thin trace, click at center should miss
    const thinResult = hitTestTrace(makeSnapshot([thinTrace]), vp, 400, 300, 5);
    expect(thinResult).toBeNull();

    // With wide trace, click at center should hit
    const wideResult = hitTestTrace(makeSnapshot([wideTrace]), vp, 400, 300, 5);
    expect(wideResult).not.toBeNull();
    expect(wideResult!.trace.id).toEqual(2);
  });

  it('returns null for null snapshot', () => {
    const vp = makeViewport();
    const result = hitTestTrace(null, vp, 400, 300, 5);
    expect(result).toBeNull();
  });

  it('returns null for empty traces', () => {
    const vp = makeViewport();
    const result = hitTestTrace(makeSnapshot([]), vp, 400, 300, 5);
    expect(result).toBeNull();
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { UndoStack, type BoardCommand } from '../undo';

/** Create a mock command that tracks execute/undo calls via a shared log array */
function mockCmd(name: string, log: string[]): BoardCommand {
  return {
    description: name,
    execute: vi.fn(() => log.push(`exec:${name}`)),
    undo: vi.fn(() => log.push(`undo:${name}`)),
  };
}

describe('UndoStack', () => {
  let stack: UndoStack;
  let log: string[];

  beforeEach(() => {
    stack = new UndoStack();
    log = [];
  });

  it('starts empty — cannot undo or redo', () => {
    expect(stack.canUndo).toBe(false);
    expect(stack.canRedo).toBe(false);
    expect(stack.depth).toBe(0);
    expect(stack.lastCommand).toBeNull();
  });

  it('push executes the command and adds to stack', () => {
    const cmd = mockCmd('A', log);
    stack.push(cmd);

    expect(cmd.execute).toHaveBeenCalledOnce();
    expect(stack.canUndo).toBe(true);
    expect(stack.canRedo).toBe(false);
    expect(stack.depth).toBe(1);
    expect(stack.lastCommand).toBe('A');
    expect(log).toEqual(['exec:A']);
  });

  it('undo reverts the last command', () => {
    const cmd = mockCmd('A', log);
    stack.push(cmd);
    stack.undo();

    expect(cmd.undo).toHaveBeenCalledOnce();
    expect(stack.canUndo).toBe(false);
    expect(stack.canRedo).toBe(true);
    expect(log).toEqual(['exec:A', 'undo:A']);
  });

  it('redo re-applies the undone command', () => {
    const cmd = mockCmd('A', log);
    stack.push(cmd);
    stack.undo();
    stack.redo();

    expect(cmd.execute).toHaveBeenCalledTimes(2); // once in push, once in redo
    expect(stack.canUndo).toBe(true);
    expect(stack.canRedo).toBe(false);
    expect(log).toEqual(['exec:A', 'undo:A', 'exec:A']);
  });

  it('undo past empty is a no-op', () => {
    stack.undo(); // nothing to undo
    expect(stack.canUndo).toBe(false);
    expect(stack.canRedo).toBe(false);
    expect(log).toEqual([]);
  });

  it('redo past head is a no-op', () => {
    const cmd = mockCmd('A', log);
    stack.push(cmd);
    stack.redo(); // already at head, nothing to redo
    expect(cmd.execute).toHaveBeenCalledOnce(); // only the initial push
    expect(log).toEqual(['exec:A']);
  });

  it('push after undo clears the redo branch', () => {
    const cmdA = mockCmd('A', log);
    const cmdB = mockCmd('B', log);
    const cmdC = mockCmd('C', log);

    stack.push(cmdA);
    stack.push(cmdB);
    stack.undo(); // undo B, now B is in redo
    expect(stack.canRedo).toBe(true);

    stack.push(cmdC); // should clear B from redo
    expect(stack.canRedo).toBe(false);
    expect(stack.depth).toBe(2); // A, C (B was discarded)
    expect(stack.lastCommand).toBe('C');
  });

  it('capacity limit drops oldest commands', () => {
    // Push 105 commands — stack should keep max 100
    for (let i = 0; i < 105; i++) {
      stack.push(mockCmd(`cmd${i}`, log));
    }
    expect(stack.depth).toBe(100);
    // Last command should be cmd104
    expect(stack.lastCommand).toBe('cmd104');
    // Can still undo
    expect(stack.canUndo).toBe(true);
  });

  it('multi-step undo/redo sequence', () => {
    const cmdA = mockCmd('A', log);
    const cmdB = mockCmd('B', log);
    const cmdC = mockCmd('C', log);

    stack.push(cmdA);
    stack.push(cmdB);
    stack.push(cmdC);

    stack.undo(); // undo C
    stack.undo(); // undo B
    expect(stack.lastCommand).toBe('A');
    expect(stack.canRedo).toBe(true);

    stack.redo(); // redo B
    expect(stack.lastCommand).toBe('B');

    expect(log).toEqual([
      'exec:A', 'exec:B', 'exec:C',
      'undo:C', 'undo:B',
      'exec:B',
    ]);
  });

  it('clear empties the entire stack', () => {
    stack.push(mockCmd('A', log));
    stack.push(mockCmd('B', log));
    stack.clear();

    expect(stack.canUndo).toBe(false);
    expect(stack.canRedo).toBe(false);
    expect(stack.depth).toBe(0);
    expect(stack.lastCommand).toBeNull();
  });
});

import { describe, it, expect, vi, afterEach } from 'vitest';
import { encodeViewState, decodeViewState, type ViewState } from '../url-state';

/**
 * decodeViewState reads window.location.search, so we need to mock it.
 * We use Object.defineProperty to set a custom search string per test.
 */
function mockLocationSearch(search: string): void {
  Object.defineProperty(globalThis, 'window', {
    value: { location: { search } },
    writable: true,
    configurable: true,
  });
}

afterEach(() => {
  // Clean up window mock
  if ('window' in globalThis) {
    delete (globalThis as any).window;
  }
});

describe('encodeViewState', () => {
  it('encodes a typical view state to query string', () => {
    const state: ViewState = {
      layers: ['top', 'bottom', 'ratsnest'],
      zoom: 1.5,
      panX: 1000,
      panY: -2000,
    };
    const qs = encodeViewState(state);
    expect(qs).toContain('l=top%2Cbottom%2Cratsnest');
    expect(qs).toContain('z=1.50');
    expect(qs).toContain('x=1000');
    expect(qs).toContain('y=-2000');
    expect(qs.startsWith('?')).toBe(true);
  });

  it('handles single layer', () => {
    const state: ViewState = { layers: ['top'], zoom: 1, panX: 0, panY: 0 };
    const qs = encodeViewState(state);
    expect(qs).toContain('l=top');
  });

  it('rounds panX and panY to integers', () => {
    const state: ViewState = { layers: ['top'], zoom: 1, panX: 123.456, panY: -789.999 };
    const qs = encodeViewState(state);
    expect(qs).toContain('x=123');
    expect(qs).toContain('y=-790');
  });

  it('handles zero values', () => {
    const state: ViewState = { layers: ['top'], zoom: 0, panX: 0, panY: 0 };
    const qs = encodeViewState(state);
    expect(qs).toContain('z=0.00');
    expect(qs).toContain('x=0');
    expect(qs).toContain('y=0');
  });
});

describe('encodeViewState / decodeViewState roundtrip', () => {
  it('roundtrips a typical state', () => {
    const original: ViewState = {
      layers: ['top', 'bottom'],
      zoom: 2.5,
      panX: 5000,
      panY: -3000,
    };
    const qs = encodeViewState(original);
    mockLocationSearch(qs);
    const decoded = decodeViewState();

    expect(decoded).not.toBeNull();
    expect(decoded!.layers).toEqual(['top', 'bottom']);
    expect(decoded!.zoom).toBeCloseTo(2.5, 1);
    expect(decoded!.panX).toEqual(5000);
    expect(decoded!.panY).toEqual(-3000);
  });

  it('handles large coordinate values', () => {
    const original: ViewState = {
      layers: ['top'],
      zoom: 0.001,
      panX: 999_999_999,
      panY: -999_999_999,
    };
    const qs = encodeViewState(original);
    mockLocationSearch(qs);
    const decoded = decodeViewState();

    expect(decoded).not.toBeNull();
    expect(decoded!.panX).toEqual(999999999);
    expect(decoded!.panY).toEqual(-999999999);
  });
});

describe('decodeViewState', () => {
  it('returns null when no layer param present', () => {
    mockLocationSearch('?z=1&x=0&y=0');
    const result = decodeViewState();
    expect(result).toBeNull();
  });

  it('returns defaults for missing numeric params', () => {
    mockLocationSearch('?l=top');
    const result = decodeViewState();
    expect(result).not.toBeNull();
    expect(result!.layers).toEqual(['top']);
    expect(result!.zoom).toEqual(1);   // default
    expect(result!.panX).toEqual(0);   // default
    expect(result!.panY).toEqual(0);   // default
  });

  it('handles negative zoom gracefully', () => {
    mockLocationSearch('?l=top&z=-5&x=0&y=0');
    const result = decodeViewState();
    expect(result).not.toBeNull();
    expect(result!.zoom).toEqual(-5); // no clamping in decode — caller's responsibility
  });
});

